            user_parts.append(f"✗ Failed: {', '.join([f'{c} ({e})' for c, e in failed])}")

        user_response = "\n".join(user_parts) or "No containers to stop"

        llm_response = f"Stop operation: {len(stopped)} succeeded, {len(failed)} failed"

        logger.info(f"Stopped {len(stopped)} container(s)")

        return ToolResponse(user_response=user_response, llm_response=llm_response)

    except Exception as e:
        error_msg = str(e)
        logger.error(f"Error stopping containers: {error_msg}")
        return ToolResponse(
            user_response=f"❌ Error: {error_msg}",
            llm_response=f"Stop operation failed: {error_msg}"
        )


def docker_restart(
    container: Union[str, List[str]],
    timeout: int = 10,
    **kwargs
) -> ToolResponse:
    """
    Restart one or more containers in the project.

    Args:
        container: Container name/ID or list of container names/IDs.
        timeout: Timeout in seconds before killing during stop (default: 10).
        **kwargs: Additional arguments including settings (CODXJuniorSettings).

    Returns:
        ToolResponse: Contains:
            - user_response: Status of restarted containers for user display.
            - llm_response: Summary of restart operations for LLM.

    Raises:
        Exception: If project settings are not provided.
    """
    settings: CODXJuniorSettings = kwargs.get("settings")
    if not settings:
        raise Exception("Invalid project settings")

    try:
        # Normalize to list
        containers = [container] if isinstance(container, str) else container

        if not containers:
            raise ValueError("At least one container must be specified")

        restarted = []
        failed = []

        for cont in containers:
            # Validate container ownership
            if not _validate_container_ownership(settings, cont):
                failed.append((cont, "Access denied"))
                continue

            try:
                cmd = f"docker restart --time {timeout} {cont}"
                stdout, stderr = execute_command(cmd, timeout=DOCKER_TIMEOUT)

                if stderr and "error" in stderr.lower():
                    failed.append((cont, stderr))
                else:
                    restarted.append(cont)
            except Exception as e:
                failed.append((cont, str(e)))

        # Build response
        user_parts = []
        if restarted:
            user_parts.append(f"✓ Restarted: {', '.join(restarted)}")
        if failed:
            user_parts.append(f"✗ Failed: {', '.join([f'{c} ({e})' for c, e in failed])}")

        user_response = "\n".join(user_parts) or "No containers to restart"

        llm_response = f"Restart operation: {len(restarted)} succeeded, {len(failed)} failed"

        logger.info(f"Restarted {len(restarted)} container(s)")

        return ToolResponse(user_response=user_response, llm_response=llm_response)

    except Exception as e:
        error_msg = str(e)
        logger.error(f"Error restarting containers: {error_msg}")
        return ToolResponse(
            user_response=f"❌ Error: {error_msg}",
            llm_response=f"Restart operation failed: {error_msg}"
        )

